// Pure helpers of the first-time School setup page (views/admin/SchoolSetup): reading a paste from Excel, checking the rows,
// building the requests, the default settings and the list of generated logins.

import * as XLSX from 'xlsx';

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Text copied from Excel (tab between cells, new line between rows) -> rows of cells. A first row that looks like the sheet's
// header ("Name", "Teacher name" ...) is dropped when more rows follow.
export const parsePaste = (text, headerPattern) => {
  const lines = String(text || '')
    .replace(/\r/g, '')
    .split('\n');
  if (lines.length && lines[lines.length - 1] === '') lines.pop();
  const rows = lines.map(line => line.split('\t').map(cell => cell.trim().replace(/^"(.*)"$/, '$1')));
  if (headerPattern && rows.length > 1 && headerPattern.test(rows[0][0] || '')) rows.shift();
  return rows;
};

// ---------------------------------------------------------------- Excel sheets (paste, file upload) -> grid rows
// A sheet from the school may have its columns in any order, with extra columns (S.No, Class ...) and a header row, or none of that.
// So a table is read like this: if the first row names the grid's columns ("Name", "Email id", "Mobile" ...) the cells are matched by
// those names and every other column is ignored; otherwise the cells go into the grid's columns in order, starting at the box that was
// clicked, and a leading serial-number column (1, 2, 3 ...) is dropped.

// "Email ID", "e-mail" and "EMAIL" are all the same header
export const headerKey = text =>
  String(text == null ? '' : text)
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');

const baseLabel = label =>
  String(label)
    .replace(/\(.*?\)/g, '')
    .replace('*', '')
    .trim();
// the header names a grid column answers to: its own label and the column's aliases
const columnKeys = column => new Set([headerKey(baseLabel(column.label)), ...(column.aliases || []).map(headerKey)]);

// Text copied from Excel -> table of cells (rows with nothing in them at the end are dropped).
export const splitTable = text => {
  const lines = String(text || '')
    .replace(/\r/g, '')
    .split('\n');
  const rows = lines.map(line => line.split('\t').map(cell => cell.trim().replace(/^"(.*)"$/, '$1')));
  while (rows.length && rows[rows.length - 1].every(cell => cell === '')) rows.pop();
  return rows;
};

// A cell for a drop-down column: the option it means ("teacher" -> Teaching), the column's default when empty, null when it is not
// one of the options. Other columns: the text itself.
export const normalizeCell = (column, text) => {
  const value = String(text == null ? '' : text).trim();
  if (!column.options) return value;
  if (value === '') return column.def || '';
  const key = headerKey(value);
  const hit = column.options.find(
    option => headerKey(option) === key || (column.synonyms?.[option] || []).some(word => headerKey(word) === key)
  );
  return hit === undefined ? null : hit;
};

// table -> { rows, mode, matched, ignored }. rows: one array per data row with a cell for every grid column, undefined = "not in the
// sheet, leave the box as it is". mode: 'header' (matched by the first row's names) or 'position' (in order from startCol).
// matched / ignored: the grid columns found and the sheet columns not used (header mode only).
export const placeTable = (table, columns, startCol = 0) => {
  const keys = columns.map(columnKeys);
  const hitsOf = row => (row || []).map(cell => keys.findIndex(set => set.has(headerKey(cell))));
  // The header is usually the first row, but a school's sheet may have a title or blank lines above it: look in the first rows for one
  // that names two or more columns (one is enough in the very first row). A row with an email in it is data, never a header.
  let headerAt = -1;
  for (let i = 0; i < Math.min(table.length, 6) && headerAt < 0; i += 1) {
    const found = new Set(hitsOf(table[i]).filter(j => j >= 0)).size;
    if ((found >= 2 || (found >= 1 && i === 0)) && !table[i].some(cell => EMAIL.test(String(cell).trim())))
      headerAt = i;
  }
  if (headerAt >= 0) {
    const first = table[headerAt];
    const hits = hitsOf(first);
    const source = columns.map((c, j) => hits.indexOf(j));
    const rows = table
      .slice(headerAt + 1)
      .map(cells => source.map(i => (i < 0 ? undefined : cells[i] === undefined ? '' : cells[i])));
    return {
      rows,
      mode: 'header',
      skippedAbove: headerAt,
      matched: columns.filter((c, j) => source[j] >= 0).map(c => baseLabel(c.label)),
      ignored: first.filter((cell, i) => hits[i] < 0 && String(cell).trim() !== ''),
    };
  }
  let cells = table;
  const width = Math.max(0, ...table.map(row => row.length));
  const serial = row => /^\d{1,5}\.?$/.test(row[0] || '');
  if (startCol === 0 && width > 1 && cells.some(serial) && cells.every(row => serial(row) || !row[0])) {
    cells = cells.map(row => row.slice(1));
  }
  const rows = cells.map(row =>
    columns.map((c, j) => (j < startCol || j - startCol >= row.length ? undefined : row[j - startCol]))
  );
  return { rows, mode: 'position', matched: [], ignored: [], dropped: cells === table ? 0 : 1 };
};

// An uploaded .xlsx / .xls / .csv file -> table of cells (the first sheet that has something in it).
export const readSheetFile = async file => {
  const book = XLSX.read(await file.arrayBuffer(), { type: 'array' });
  const read = name =>
    XLSX.utils.sheet_to_json(book.Sheets[name], { header: 1, raw: false, defval: '', blankrows: false });
  const name = book.SheetNames.find(n => read(n).length) || book.SheetNames[0];
  return (name ? read(name) : []).map(row => row.map(cell => String(cell == null ? '' : cell).trim()));
};

// A blank sheet with the grid's headers (and a sample row) to fill in and upload.
export const downloadTemplate = (fileName, columns, sample) => {
  const sheet = XLSX.utils.aoa_to_sheet([columns.map(c => baseLabel(c.label)), ...(sample || [])]);
  sheet['!cols'] = columns.map(c => ({ wch: Math.max(14, Math.round((c.width || 110) / 8)) }));
  const book = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(book, sheet, 'Sheet1');
  XLSX.writeFile(book, fileName);
};

// Does a paste have more than one cell or row (so it should fill the grid) - or is it a single value to type normally?
export const isGridPaste = text => /[\t\n\r]/.test(String(text || '').replace(/[\n\r]+$/, ''));

export const isBlankRow = (values, defaults = []) => values.every((value, i) => (value || '') === (defaults[i] || ''));

// Name and Email are the first two columns of both the teachers and the admins grid. There is no password column: every new
// login starts with the app's default password (the same as every other way of adding a user) and the person changes it later.
// Returns [[columnIndex, message], ...] (empty = the row is fine).
export const personErrors = (values, index, rows) => {
  const errors = [];
  const [name, email] = values;
  if (!name || name.trim().length < 3) errors.push([0, 'Name needs 3+ characters']);
  if (!email) errors.push([1, 'Email is required']);
  else if (!EMAIL.test(email)) errors.push([1, 'Email is not valid']);
  else if (rows.some((other, i) => i !== index && String(other[1] || '').toLowerCase() === email.toLowerCase())) {
    errors.push([1, 'Duplicate email in the sheet']);
  }
  return errors;
};

const clean = value => {
  const text = String(value == null ? '' : value).trim();
  return text === '' ? undefined : text;
};

// An employee row: Name, Email, Type (Teaching / Non-teaching = a worker), Staff code, Qualification, Department, Phone, WhatsApp.
export const EMPLOYEE_TYPES = ['Teaching', 'Non-teaching', 'Driver'];
export const teacherBody = values => ({
  name: clean(values[0]),
  email: clean(values[1]),
  profession: values[2] === 'Non-teaching' ? 'NON_TEACHING' : 'TEACHING',
  code: clean(values[3]),
  qualification: clean(values[4]),
  department: clean(values[5]),
  phoneNumber: clean(values[6]) || '', // the employee table does not accept an empty (null) phone
  whatsAppNumber: clean(values[7]),
});

// A Driver row goes to the driver endpoint (the same one the Transport page uses), which makes the employee and its login.
export const driverBody = (values, schoolId) => ({
  name: clean(values[0]),
  email: clean(values[1]),
  code: clean(values[3]),
  qualification: clean(values[4]),
  phoneNumber: clean(values[6]) || '', // the employee table does not accept an empty (null) phone
  whatsAppNumber: clean(values[7]),
  employerOrgId: schoolId,
  designation: 'Driver',
  department: 'Transport',
  status: 'ACTIVE',
});

// ---------------------------------------------------------------- the school's own classes, subjects and their teachers

// One row per class and subject taken from the school's sheet: Class, Subject, Level. Rows with the same Class make one class.
export const CLASS_LEVELS = ['Primary', 'Secondary', 'Higher secondary', 'General'];
const LEVEL_VALUES = {
  Primary: 'PRIMARY',
  Secondary: 'SECONDARY',
  'Higher secondary': 'HIGHER_SECONDARY',
  General: 'GENERAL',
};

// a name as the sheet and the pages may spell it differently: no case, no extra spaces
export const normalizeName = text =>
  String(text == null ? '' : text)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

// a short code from a name: letters and digits only, upper case, at most max characters
export const slugCode = (text, max) =>
  String(text == null ? '' : text)
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '')
    .slice(0, max);

export const classSubjectErrors = (values, index, rows) => {
  const errors = [];
  const [className, subject] = values;
  if (!clean(className)) errors.push([0, 'Class is required']);
  if (!clean(subject)) errors.push([1, 'Subject is required']);
  else if (
    clean(className) &&
    rows.some(
      (other, i) =>
        i < index &&
        normalizeName(other[0]) === normalizeName(className) &&
        normalizeName(other[1]) === normalizeName(subject)
    )
  ) {
    errors.push([1, 'This subject is already listed for the class']);
  }
  return errors;
};

// Pending grid rows [{ index, values }] -> the classes to make, in the order of the sheet:
// [{ key, name, code, studyLevel, subjects: [{ index, name, code }] }]. A class code and a subject code are made from the names; a
// class code that two classes would share gets a number.
export const groupClasses = pending => {
  const byKey = new Map();
  const usedCodes = new Set();
  pending.forEach(({ index, values }) => {
    const name = clean(values[0]);
    const key = normalizeName(name);
    if (!byKey.has(key)) {
      let code = slugCode(name, 12) || 'CLASS';
      for (let n = 2; usedCodes.has(code); n += 1) code = `${slugCode(name, 10)}${n}`;
      usedCodes.add(code);
      byKey.set(key, { key, name, code, studyLevel: LEVEL_VALUES[values[2]] || 'PRIMARY', subjects: [] });
    }
    const subject = clean(values[1]);
    byKey.get(key).subjects.push({ index, name: subject, code: slugCode(subject, 10) || 'SUBJ' });
  });
  return [...byKey.values()];
};

export const adminBody = values => ({
  name: clean(values[0]),
  email: clean(values[1]),
  role: values[2] || 'ADMIN',
});

// "email: reason" lines of a bulk result -> { email (lower case): reason }
export const errorsByEmail = errors =>
  (errors || []).reduce((acc, line) => {
    const at = String(line).indexOf(': ');
    if (at > 0) acc[line.substring(0, at).toLowerCase()] = line.substring(at + 2);
    return acc;
  }, {});

