// Only the settings changed from their default are sent: { NAME: value } or undefined when nothing changed.
export const changedSettings = (template, values) => {
  const changed = {};
  template.forEach(([name, def]) => {
    const value = String(values[name] == null ? def : values[name]).trim();
    if (value !== '' && value !== def) changed[name] = value;
  });
  return Object.keys(changed).length ? changed : undefined;
};

// The years a batch can start in: the next two, this year and the ten before it, newest first (a school can be set up with an older
// year first and the later years added on the Batches page).
export const batchYearOptions = (now = new Date().getFullYear()) => Array.from({ length: 13 }, (_, i) => now + 2 - i);

// How many classes "Create batch, classes & subjects" will make.
export const estimateClasses = ({ includeKg, fromGrade, toGrade, sections }) => {
  const names = String(sections || '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
  const standards = (includeKg ? 3 : 0) + Math.max(0, (Number(toGrade) || 12) - (Number(fromGrade) || 1) + 1);
  return { standards, sections: names.length, classes: standards * names.length };
};

// The generated logins as a sheet to paste into Excel / save as CSV.
export const credentialsTsv = creds =>
  `Name\tLogin\tRole\tPassword\n${creds.map(c => [c.name, c.login, c.role, c.password].join('\t')).join('\n')}`;
export const credentialsCsv = creds => {
  const quote = text => `"${String(text).replace(/"/g, '""')}"`;
  return `Name,Login,Role,Password\n${creds
    .map(c => [c.name, c.login, c.role, c.password].map(quote).join(','))
    .join('\n')}`;
};

// The password every new login starts with (CommonConstance.DEFAULT_PASSWORD in the backend).
export const DEFAULT_PASSWORD = 'resetPass123';
export const DEFAULT_PASSWORD_LABEL = 'Default password';

// A created user from the backend -> one line of the logins list.
export const toCredential = user => ({
  name: user.name,
  login: user.loginId,
  role: user.role,
  // the app's default password is never printed, only called "Default password"; a different password the backend made is shown
  password:
    user.temporaryPassword && user.temporaryPassword !== DEFAULT_PASSWORD
      ? user.temporaryPassword
      : DEFAULT_PASSWORD_LABEL,
});

// The two values a setting can have, taken from its default: ENABLED/DISABLED, ENABLE/DISABLE, or a language (TA/EN). The setup page
// shows a switch (or a language pick) instead of a text box, so nobody can type a value the backend does not know.
export const settingChoices = def => {
  if (def === 'ENABLED' || def === 'DISABLED') return { kind: 'switch', on: 'ENABLED', off: 'DISABLED' };
  if (def === 'ENABLE' || def === 'DISABLE') return { kind: 'switch', on: 'ENABLE', off: 'DISABLE' };
  return { kind: 'language', options: ['TA', 'EN'] };
};

// The text for a failed setup / assignment call. A server that does not have these endpoints yet answers "not found" (404): say so,
// instead of the backend's raw message. `fallback` is the usual message (formResMessage(err)).
export const SERVER_NOT_READY =
  'This feature is not available on your server yet. Please try again after the server is updated.';
export const explainApiError = (err, fallback) => (err?.response?.status === 404 ? SERVER_NOT_READY : fallback);
