import axios from 'axios';
import constants from '../../config/constants';

// School setup and subject assignment, both under /api/onboarding/{schoolId} (school admin / super admin only).
//   setup:       status, initialize (batch + classes + subjects, once), setup (admin/dean logins + configuration, once),
//                admins, teachers (bulk), config, module permissions
//   assignment:  subjects (each with its teacher), assign one, assign many, remove
const baseUrl = schoolId => `${constants.API_BASE_URL}/api/onboarding/${schoolId}`;
const header = token => constants.setHeader(token);
const data = res => res.data;

export const fetchSetupStatusApi = ({ token, schoolId }) =>
  axios.get(`${baseUrl(schoolId)}/status`, header(token)).then(data);

export const initializeSchoolApi = ({ token, schoolId, postData }) =>
  axios.post(`${baseUrl(schoolId)}/initialize`, postData, header(token)).then(data);

export const setupSchoolApi = ({ token, schoolId, postData }) =>
  axios.post(`${baseUrl(schoolId)}/setup`, postData, header(token)).then(data);

export const addAdminApi = ({ token, schoolId, postData }) =>
  axios.post(`${baseUrl(schoolId)}/admins`, postData, header(token)).then(data);

export const addTeachersApi = ({ token, schoolId, postData }) =>
  axios.post(`${baseUrl(schoolId)}/teachers`, postData, header(token)).then(data);

export const fetchSetupConfigApi = ({ token, schoolId }) =>
  axios.get(`${baseUrl(schoolId)}/config`, header(token)).then(data);

export const updateSetupConfigApi = ({ token, schoolId, name, environment, value }) =>
  axios
    .put(
      `${baseUrl(schoolId)}/config/${encodeURIComponent(name)}`,
      { value },
      { ...header(token), params: { environment } }
    )
    .then(data);

export const fetchModulePermissionsApi = ({ token, schoolId }) =>
  axios.get(`${baseUrl(schoolId)}/module-permissions`, header(token)).then(data);

export const updateModulePermissionApi = ({ token, schoolId, moduleName, postData }) =>
  axios
    .put(`${baseUrl(schoolId)}/module-permissions/${encodeURIComponent(moduleName)}`, postData, header(token))
    .then(data);

export const fetchSubjectTeachersApi = ({ token, schoolId }) =>
  axios.get(`${baseUrl(schoolId)}/subjects`, header(token)).then(data);

export const assignSubjectTeacherApi = ({ token, schoolId, subjectId, employeeId }) =>
  axios.put(`${baseUrl(schoolId)}/subjects/${subjectId}/teacher`, { employeeId }, header(token)).then(data);

export const assignSubjectTeachersApi = ({ token, schoolId, items }) =>
  axios.post(`${baseUrl(schoolId)}/teacher-assignments`, items, header(token)).then(data);

export const removeSubjectTeacherApi = ({ token, schoolId, subjectId }) =>
  axios.delete(`${baseUrl(schoolId)}/subjects/${subjectId}/teacher`, header(token));

// ---- the school's own classes and subjects (setup page, "paste my classes"): the same endpoints the Batches, Classes and Subjects
// pages use, one call per batch / class / subject.
const adminUrl = path => `${constants.API_BASE_URL}/api/admin/${path}`;

export const createBatchApi = ({ token, postData }) =>
  axios.post(adminUrl('create-batch'), postData, header(token)).then(data);

export const createCourseApi = ({ token, postData }) =>
  axios.post(adminUrl('create-course'), postData, header(token)).then(data);

// adds the class to the batch (the batch's other classes stay)
export const addCourseToBatchApi = ({ token, batch, courseId }) =>
  axios
    .put(
      adminUrl(`update-batch/${batch.batchId}`),
      {
        school: { schoolId: batch.school?.schoolId },
        batchId: batch.batchId,
        name: batch.name,
        startYear: batch.startYear,
        endYear: batch.endYear,
        courses: [{ courseId }],
      },
      header(token)
    )
    .then(data);

export const createSubjectApi = ({ token, postData }) =>
  axios.post(adminUrl('create-subject'), postData, header(token)).then(data);

// The batches of the school being set up (the school is named in the call, not taken from the school picked at the top).
export const fetchSetupBatchesApi = ({ token, schoolId }) =>
  axios.get(adminUrl(`get-school-batch/${schoolId}`), header(token)).then(data);

// The classes that belong to one batch (a school can have several batches, each with its own classes).
export const fetchBatchClassesApi = ({ token, schoolId, batchId }) =>
  axios.get(`${constants.API_BASE_URL}/api/promotion/${schoolId}/batches/${batchId}/courses`, header(token)).then(data);
